// into all 48 output channels. 256 threads = 16 spatial groups (4 ld positions each) x 16 groups of 3 oc, using 2D register blocking so each staged activation and weight is reused from registers.
__global__ void convt3d48_k3_kernel(
    const float* __restrict__ X,
    const float* __restrict__ W,
    const float* __restrict__ B,
    float* __restrict__ Y,
    const int Din, const int Hin, const int Win,
