    for (int p = 0; p < 4; ++p) {
      acc[p][i] = bv;
    }
  }
  for (int ic = 0; ic < CIN; ++ic) {
    const int cur = ic & 1;
    const int nxt = cur ^ 1;
    // Overlap the next weight-slice load with the current compute phase.
    if (ic + 1 < CIN) {
      for (int idx = tid; idx < COUT * 27; idx += blockDim.x) {
        const int oc  = idx / 27;
